operation.add:
// WT Filter start
$this->document->addStyle('view/stylesheet/wt_filter/wt_filter.css');
$this->document->addScript('view/javascript/wt_filter/wt_filter.js');
// WT Filter end

// WT Filter start
$data['tab_wt_filter'] = $this->language->get('tab_wt_filter');
$data['entry_values'] = $this->language->get('entry_values');
$data['wt_filter_select_category'] = $this->language->get('wt_filter_select_category');
// WT Filter end

// WT Filter start
if ($this->user->hasPermission('access', 'catalog/wt_filter')) {
	$catalog[] = array(
		'name'	   => $this->language->get('text_wt_filter'),
		'href'     => $this->url->link('catalog/wt_filter', 'user_token=' . $this->session->data['user_token'], true),
		'children' => array()
	);
}
// WT Filter end

// WT Filter start
$_['entry_values']               = 'Add values for this option.';
$_['tab_wt_filter']              = 'Filter options';
$_['wt_filter_select_category']  = 'First select a category for this product.';
// WT Filter end

// WT Filter start
$_['text_wt_filter'] = 'WT Filter';
// WT Filter end

// WT Filter start
$_['entry_values']               = 'Додайте значення для цієї опції.';
$_['tab_wt_filter']              = 'Опції фільтра';
$_['wt_filter_select_category']  = 'Спочатку виберіть категорію для цього товару.';
// WT Filter end

// WT Filter start
$_['text_wt_filter'] = 'WT Filter';
// WT Filter end

// WT Filter start
$this->db->query("DELETE FROM " . DB_PREFIX . "wt_filter_option_value_to_product WHERE product_id = '" . (int)$product_id . "'");

if (isset($data['wt_filter_product_option'])) {
	foreach ($data['wt_filter_product_option'] as $option_id => $values) {
		foreach ($values['values'] as $value_id => $value) {
			if (isset($value['selected'])) {
				$this->db->query("INSERT INTO " . DB_PREFIX . "wt_filter_option_value_to_product SET product_id = '" . (int)$product_id . "', option_id = '" . (int)$option_id . "', value_id = '" . (string)$value_id . "', slide_value_min = '" . (isset($value['slide_value_min']) ? (float)$value['slide_value_min'] : 0) . "', slide_value_max = '" . (isset($value['slide_value_max']) ? (float)$value['slide_value_max'] : 0) . "'");
			}
		}
	}
}
// WT Filter end

// WT Filter start
$this->load->model('catalog/wt_filter');
if (method_exists($this->model_catalog_wt_filter, 'getProductWtFilterValues')) {
	$data['wt_filter_product_option'] = $this->model_catalog_wt_filter->getProductWtFilterValues($product_id);
}
// WT Filter end

// WT Filter start
$this->db->query("DELETE FROM " . DB_PREFIX . "wt_filter_option_value_to_product WHERE product_id = '" . (int)$product_id . "'");
// WT Filter end

{# WT Filter start #}
<script type="text/javascript"><!--
wt_filter = wt_filter || {};
wt_filter.php = {
	text_select: '{{ text_select|e('js') }}',
	wt_filter_select_category: '{{ wt_filter_select_category|e('js') }}',
	entry_values: '{{ entry_values|e('js') }}',
	tab_wt_filter: '{{ tab_wt_filter|e('js') }}'
};

wt_filter.php.languages = [];
{% for language in languages %}
wt_filter.php.languages.push({
	'language_id': {{ language.language_id }},
	'name': '{{ language.name|e('js') }}',
	'image': '{{ language.code }}.png'
});
{% endfor %}
//--></script>
{# WT Filter end #}

// WT Filter start
if (is_file(DIR_APPLICATION . 'controller/extension/module/wt_filter.php')) {
	$this->load->controller('extension/module/wt_filter/initialise');
}
// WT Filter end

// WT Filter start
if (!is_null($this->registry->get('wt_filter'))) {
	$this->url->addRewrite($this->registry->get('wt_filter'));
}
// WT Filter end

// WT Filter start
if (!empty($data['filter_wt_filter'])) {
	$this->load->model('catalog/wt_filter');
	$wt_filter_product_sql = $this->model_catalog_wt_filter->getProductSQL($data['filter_wt_filter']);
	if ($wt_filter_product_sql) {
		$sql .= $wt_filter_product_sql;
	}
}
// WT Filter end

// WT Filter start
if (isset($this->request->get['filter_wt_filter'])) {
	$filter_wt_filter = $this->request->get['filter_wt_filter'];
} else {
	$filter_wt_filter = '';
}
// WT Filter end

// WT Filter start
$filter_data['filter_wt_filter'] = $filter_wt_filter;
// WT Filter end

// WT Filter start
if (isset($this->request->get['filter_wt_filter'])) {
	$url .= '&filter_wt_filter=' . urlencode($this->request->get['filter_wt_filter']);
}
// WT Filter end

// WT Filter start
public function setNoindex($state = false) {
	if ($state) {
		$this->setRobots('noindex,nofollow');
	}
}

public function isNoindex() {
	return (strpos((string)$this->robots, 'noindex') !== false);
}
